<?php
declare(strict_types=1);
namespace App\Modules\Tourism\Services;
use App\Modules\Tourism\Models\TourismRoom;use App\Modules\Tourism\Models\TourismStay;use RuntimeException;
final class TourismRoomService{private TourismRoom $m;private TourismStay $stays;public function __construct(){$this->m=new TourismRoom();$this->stays=new TourismStay();}public function store(int $t,int $stay,array $i,int $u):int{$this->checkStay($t,$stay);return $this->m->create($t,$stay,$this->validate($i),$u);}public function update(int $t,int $stay,int $id,array $i,int $u):void{$this->checkStay($t,$stay);$r=$this->m->find($t,$id);if(!$r||((int)$r['stay_id']!==$stay))throw new RuntimeException('Room type not found.');$this->m->update($t,$id,$this->validate($i),$u);}public function delete(int $t,int $stay,int $id,int $u):void{$this->checkStay($t,$stay);$r=$this->m->find($t,$id);if(!$r||((int)$r['stay_id']!==$stay))throw new RuntimeException('Room type not found.');$this->m->delete($t,$id,$u);}public function restore(int $t,int $stay,int $id,int $u):void{$this->checkStay($t,$stay);$r=$this->m->find($t,$id,true);if(!$r||((int)$r['stay_id']!==$stay))throw new RuntimeException('Deleted room type not found.');$this->m->restore($t,$id,$u);}private function checkStay(int $t,int $id):void{if(!$this->stays->find($t,$id))throw new RuntimeException('Stay not found.');}private function validate(array $i):array{$d=['name'=>trim((string)($i['name']??'')),'description'=>trim((string)($i['description']??''))?:null,'bed_type'=>trim((string)($i['bed_type']??''))?:null,'max_guests'=>max(1,(int)($i['max_guests']??1)),'quantity'=>max(1,(int)($i['quantity']??1)),'price_per_night'=>number_format((float)($i['price_per_night']??0),2,'.',''),'status'=>trim((string)($i['status']??'Active'))?:'Active'];if(!$d['name'])throw new RuntimeException('Room type name is required.');if((float)$d['price_per_night']<0)throw new RuntimeException('Room price cannot be negative.');if(!in_array($d['status'],['Active','Inactive'],true))throw new RuntimeException('Invalid room status.');return $d;}}
